messages.content:
Tool response:
Tool: search_visits
Description: Search Visits
Parameters:
    {
      "type": "object",
      "properties": {
        "office_name": {
          "type": "string",
          "description": "Name of the office to filter visits by",
          "title": "Office Name"
        },
        "start_time": {
          "type": "string",
          "description": "Start datetime for the search window in ISO format",
          "title": "Start Time"
        },
        "end_time": {
          "type": "string",
          "description": "End datetime for the search window in ISO format",
          "title": "End Time"
        },
        "host_name": {
          "type": "string",
          "description": "Full name of the host user to filter visits by",
          "title": "Host Name"
        }
      },
      "required": [
        "office_name",
        "start_time",
        "end_time",
        "host_name"
      ]
    }
